<?php
$pageTitle='Book Availability Search'; require __DIR__.'/config/database.php'; require __DIR__.'/includes/header.php';
$q=trim($_GET['q']??''); $rows=[];
if($q!==''){$s=$pdo->prepare("SELECT b.*,c.name category,a.name author,(b.total_copies-b.available_copies) issued_copies FROM books b LEFT JOIN categories c ON c.id=b.category_id LEFT JOIN authors a ON a.id=b.author_id WHERE b.status='active' AND (b.title LIKE ? OR b.isbn LIKE ? OR b.accession_no LIKE ? OR a.name LIKE ? OR c.name LIKE ?) ORDER BY b.title");$like="%$q%";$s->execute([$like,$like,$like,$like,$like]);$rows=$s->fetchAll();}
?><h2>Book Availability Search</h2><form class="input-group mb-4"><input class="form-control" name="q" value="<?=h($q)?>" placeholder="Title, ISBN, accession number, author or category"><button class="btn btn-primary">Search</button></form>
<div class="card shadow-sm"><div class="card-body"><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Accession</th><th>Book Title</th><th>Author</th><th>Category</th><th>Total</th><th>Issued</th><th>Available</th><th>Shelf</th><th>Status</th></tr></thead><tbody>
<?php foreach($rows as $b): $available=(int)$b['available_copies']; ?><tr><td><?=h($b['accession_no'])?></td><td><?=h($b['title'])?></td><td><?=h($b['author']??'')?></td><td><?=h($b['category']??'')?></td><td><?=$b['total_copies']?></td><td><?=$b['issued_copies']?></td><td><strong><?=$available?></strong></td><td><?=h($b['shelf_no']??'')?></td><td><?php if($available>0): ?><span class="badge bg-success">Available</span><?php else: ?><span class="badge bg-danger">Not Available</span><?php endif; ?></td></tr><?php endforeach; ?>
<?php if($q!==''&&!$rows): ?><tr><td colspan="9" class="text-center text-muted">No books found.</td></tr><?php elseif($q===''): ?><tr><td colspan="9" class="text-center text-muted">Enter a search term to check availability.</td></tr><?php endif; ?></tbody></table></div></div></div>
<?php require __DIR__.'/includes/footer.php';